#include <iostream>
#include <string>
#include <utility>
#include <vector>

struct Tracer
{
    std::string name{};
    explicit Tracer(std::string n) : name{ std::move(n) } { std::cout << "  make " << name << '\n'; }
    Tracer(const Tracer& other) : name{ other.name } { std::cout << "  COPY " << name << '\n'; }
    Tracer(Tracer&& other) noexcept : name{ std::move(other.name) } { std::cout << "  move " << name << '\n'; }
};

struct Holder
{
    Tracer inside;
    explicit Holder(Tracer t) : inside{ std::move(t) } {}
};

template <typename T, typename... Args>
T makeObject(Args&&... args)
{
    return T{ std::forward<Args>(args)... };
}

