int main()
{
    Tracer a{ "a" };
    std::cout << "makeObject<Holder>(a):\n";
    Holder h1{ makeObject<Holder>(a) };            // expected: one copy (a is an lvalue), one move into inside
    std::cout << "makeObject<Holder>(std::move(a)):\n";
    Holder h2{ makeObject<Holder>(std::move(a)) }; // expected: no copies
